css:
.bk-stage { height: 430px; border-radius: 8px; }
.ct { display: flex; flex-direction: column; gap: 10px; min-width: 0; min-height: 0; }
.ct-stage { position: relative; flex: 1 1 auto; min-height: 0; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.bk-stage canvas, .ct-stage canvas { touch-action: none; cursor: grab; }
.bk-stage canvas.holding, .ct-stage canvas.holding { cursor: grabbing; }
.ct-out { margin: 0; font-size: 22px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 2.2em; }
.ct-out small { display: block; font-size: 18px; color: var(--ink-2); }

